// Personal-library Home. All reading/account state is supplied by the existing app.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art=name=>`<img src="illustration-pack/${name}.png" alt="" loading="lazy">`;
export function renderPersonalHome(m){
 const {profile,verse,icon,section='Library'}=m;
 const tabs=`<div class="e-collections" aria-label="Home sections">${['Library','Bookmarks','Notes'].map(x=>`<button data-home-section="${x}" aria-pressed="${section===x}">${x}</button>`).join('')}</div>`;
 const header=`<header class="e-toolbar"><h1>Home</h1><div><button class="icon-button" data-nr="home-search" aria-label="Search Scripture">${icon('search')}</button><button class="icon-button" data-nr="settings" aria-label="Settings">${icon('gear')}</button></div></header><section class="e-identity compact"><button class="e-portrait" data-nr="account" aria-label="Edit your profile"><img src="${esc(profile.photo||'assets/quiet-meadow.png')}" alt="Your profile photo"></button><div class="e-identity-copy"><div class="e-name-line"><button class="e-name" data-nr="account" aria-label="Edit profile for ${esc(profile.name)}">${esc(profile.name)}</button><button class="e-inline-streak" data-nr="progress" aria-label="${m.streak}-day reading streak"><span class="e-streak-count">${icon('flame')}<strong>${m.streak}</strong></span><small>day streak</small></button></div><p>${esc(profile.bio)}</p></div></section>`;
 const verseBlock=`<section class="e-verse" aria-label="Verse of the Day"><div class="e-section-title"><h2>Verse of the Day</h2><button data-save="${esc(verse.id)}" aria-label="Save daily verse" aria-pressed="${verse.saved}">${icon('heart')}</button></div><blockquote>${esc(verse.text)}</blockquote><div class="e-verse-end"><span>${esc(verse.ref)} · ${esc(verse.translation)}</span><button data-home-open="${esc(verse.id)}">Read & reflect ${icon('arrow')}</button><button data-share="${esc(verse.id)}" aria-label="Share daily verse">${icon('share')}</button></div></section>`;
 function readingRow({artwork,title,meta,detail,attributes}){return `<button class="e-reading-row" ${attributes}><span class="e-row-image">${art(artwork)}</span><span class="e-row-copy"><h3>${esc(title)}</h3><span>${esc(meta)}</span><small>${esc(detail)}</small></span><span class="e-row-arrow">${icon('arrow')}</span></button>`}
 const rows=[readingRow({artwork:'devotional-teacup',title:m.devotional?.title||'Today’s devotional',meta:'Today’s devotional',detail:m.devotional?`${m.devotional.minutes} min read${m.devotional.read?' · Read today':''}`:'Open devotional',attributes:'data-nr="devotional"'}),readingRow({artwork:'wisdom-scroll',title:m.plan?.title||'Find your reading rhythm',meta:m.plan?'Continue reading':'Reading plans',detail:m.plan?`${m.plan.done} of ${m.plan.total} passages`:'Choose a plan · Read at your own pace',attributes:'data-nr="home-plan"'}),readingRow({artwork:'reflection-quill',title:'A little space to reflect.',meta:`${verse.ref} · Your note`,detail:m.notes.some(n=>n.id===verse.id)?'Continue your verse note':'Add a note to this verse',attributes:`data-home-note="${esc(verse.id)}"`})].join('');
 function notes(){return `<section class="e-home-panel e-verse-notes" aria-label="Notes on Scripture">${m.notes.length?`<div class="e-section-title"><h2>Your verse notes</h2><span>${m.notes.length} ${m.notes.length===1?'NOTE':'NOTES'}</span></div><div class="e-note-list">${m.notes.map(n=>`<article class="e-note-item"><button class="e-note-open" data-home-note="${esc(n.id)}" aria-label="Edit note on ${esc(n.ref)}"><span class="e-note-reference">${esc(n.ref)}</span><blockquote>${esc(n.text)}</blockquote><p>${esc(n.note)}</p><span class="e-note-edit">Read verse & edit note ${icon('arrow')}</span></button><button class="text-action e-note-delete" data-home-remove-note="${esc(n.id)}">Delete note</button></article>`).join('')}</div>`:`<h2>Your notes,<br>beside the Word.</h2><p>Notes you leave on verses appear here, with their Scripture reference.</p><button class="text-action" data-home-open="${esc(verse.id)}">Read a verse & add a note ${icon('arrow')}</button>`}</section>`}
 function bookmarks(){return `<section class="e-home-panel" aria-label="Bookmarked passages">${m.bookmarks.length?`<h2>Your reading places</h2><div class="e-reading-list">${m.bookmarks.map(v=>`<div class="e-bookmark-row">${readingRow({artwork:v.art,title:v.ref,meta:'Bookmarked passage',detail:'Continue reading',attributes:`data-home-open="${esc(v.id)}"`})}<button class="text-action" data-home-remove-bookmark="${esc(v.id)}">Remove bookmark</button></div>`).join('')}</div>`:`<h2>Keep your place.</h2><p>Bookmark a verse while reading.<br>You can return to it here.</p><button class="text-action" data-home-open="${esc(verse.id)}">Open today’s reading ${icon('arrow')}</button>`}</section>`}
 const content=m.status|| (section==='Notes'?notes():section==='Bookmarks'?bookmarks():verseBlock+`<section class="e-reading-list e-home-library" aria-label="Your reading">${rows}</section>`);
 const topics=section==='Library'?`<section class="e-topics"><h2>For the season you’re in</h2><div><button data-explore-topic="Faith">${art('faith-key')}<span>Rooted in faith</span></button><button data-explore-topic="Purpose">${art('growth-vase')}<span>Your next faithful step</span></button></div></section>`:'';
 return `<section class="feed personal-home edition-ritual"><div class="e-page">${header}${tabs}${content}${topics}${m.trialNotice||''}</div>${m.navigation}<dialog id="detail-dialog" aria-labelledby="dialog-title"><div class="dialog-inner"></div></dialog></section>`;
}
